import math


def build_station_view(stations, query, scale="C"):
    if not isinstance(stations, list):
        raise TypeError("stations must be a list")
    if not isinstance(query, str) or not isinstance(scale, str):
        raise TypeError("query and scale must be strings")
    unit = scale.upper()
    if unit not in {"C", "F"}:
        raise ValueError("scale must be C or F")

    seen = set()
    selected = []
    needle = query.casefold()
    for station in stations:
        if not isinstance(station, dict):
            raise TypeError("each station must be a dictionary")
        try:
            ident = station["id"]
            name = station["name"]
            current = station["current_c"]
            forecast = station["forecast_c"]
        except KeyError as exc:
            raise ValueError("station is missing a required field") from exc
        if not isinstance(ident, str):
            raise TypeError("id must be a string")
        if not ident:
            raise ValueError("id must be a non-empty string")
        if ident in seen:
            raise ValueError("station IDs must be unique")
        seen.add(ident)
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        if not name:
            raise ValueError("name must be a non-empty string")
        if isinstance(current, bool) or not isinstance(current, (int, float)):
            raise TypeError("current_c must be a number")
        if isinstance(current, float) and not math.isfinite(current):
            raise ValueError("current_c must be finite")
        if not isinstance(forecast, list):
            raise TypeError("forecast_c must be a list")
        for value in forecast:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("forecast values must be numbers")
            if isinstance(value, float) and not math.isfinite(value):
                raise ValueError("forecast values must be finite")
        if needle in name.casefold():
            convert = (lambda value: value) if unit == "C" else (lambda value: value * 9 / 5)
            selected.append({
                "id": ident,
                "name": name,
                "current": round(convert(current), 1),
                "forecast": [round(convert(value), 1) for value in forecast],
                "unit": unit,
            })
    selected.sort(key=lambda item: (item["name"].casefold(), item["id"]))
    return selected

